"""Contract validation and process-local clock/quota state (no transport I/O)."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone
import math
import re
import threading
import time
from urllib.parse import urlsplit


class APIError(Exception):
    def __init__(self, status: int, code: str, message: str = "", headers=None):
        self.status = status
        self.code = code
        self.message = message or code.replace("_", " ")
        self.headers = dict(headers or {})
        super().__init__(self.message)


SLUG_PATTERN = re.compile(r"[A-Za-z0-9_-]{3,32}")
_TIMESTAMP_PATTERN = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z")
_EPOCH = datetime(1970, 1, 1, tzinfo=timezone.utc)


def valid_slug(value: str) -> bool:
    return isinstance(value, str) and SLUG_PATTERN.fullmatch(value) is not None


def parse_timestamp(value: str) -> int:
    """Parse exact ASCII UTC whole-second ISO; raise ValueError on invalid input."""
    if not isinstance(value, str) or _TIMESTAMP_PATTERN.fullmatch(value) is None:
        raise ValueError("expected YYYY-MM-DDTHH:MM:SSZ")
    instant = datetime(
        int(value[0:4]), int(value[5:7]), int(value[8:10]),
        int(value[11:13]), int(value[14:16]), int(value[17:19]),
        tzinfo=timezone.utc,
    )
    return (instant - _EPOCH).days * 86400 + (instant - _EPOCH).seconds


def format_timestamp(seconds: int) -> str:
    instant = _EPOCH + timedelta(seconds=seconds)
    return (
        f"{instant.year:04d}-{instant.month:02d}-{instant.day:02d}"
        f"T{instant.hour:02d}:{instant.minute:02d}:{instant.second:02d}Z"
    )


def validate_create(body: dict) -> dict:
    """Validate all create fields before resource checks; return a shallow copy."""
    if not isinstance(body, dict):
        raise APIError(400, "invalid_json")
    if "url" not in body or body.keys() - {"url", "slug", "expires_in"}:
        raise APIError(400, "invalid_request")
    url = body["url"]
    if (not isinstance(url, str) or len(url) > 2048
            or any(ord(char) < 0x21 or ord(char) == 0x7F or char.isspace() for char in url)):
        raise APIError(400, "invalid_request", "invalid url")
    try:
        parts = urlsplit(url)
        acceptable = parts.scheme.lower() in ("http", "https") and bool(parts.hostname)
    except ValueError:
        acceptable = False
    if not acceptable:
        raise APIError(400, "invalid_request", "invalid url")
    if "slug" in body and not valid_slug(body["slug"]):
        raise APIError(400, "invalid_request", "invalid slug")
    if "expires_in" in body:
        expiry = body["expires_in"]
        if type(expiry) is not int or not 1 <= expiry <= 31536000:
            raise APIError(400, "invalid_request", "invalid expires_in")
    return dict(body)


class Clock:
    def __init__(self, fake_clock: str | None = None):
        self._lock = threading.Lock()
        self._frozen = None if fake_clock is None else parse_timestamp(fake_clock)

    @property
    def is_fake(self) -> bool:
        return self._frozen is not None

    def now(self) -> int:
        with self._lock:
            return math.floor(time.time()) if self._frozen is None else self._frozen

    def set_now(self, body: dict) -> int:
        """Validate E8's object and atomically replace fake time; real clocks are 404."""
        if not self.is_fake:
            raise APIError(404, "not_found")
        if not isinstance(body, dict):
            raise APIError(400, "invalid_json")
        if body.keys() != {"now"}:
            raise APIError(400, "invalid_request")
        try:
            instant = parse_timestamp(body["now"])
        except ValueError:
            raise APIError(400, "invalid_request", "invalid now") from None
        with self._lock:
            self._frozen = instant
        return instant


class RateLimiter:
    def __init__(self, clock: Clock, limit: int = 60):
        if type(limit) is not int or limit < 1:
            raise ValueError("rate limit must be an integer >= 1")
        self.clock = clock
        self.limit = limit
        self._lock = threading.Lock()
        self._counts = {}

    def check(self, token_hash: str) -> None:
        """Count every call, including rejected ones; retain previously visited windows."""
        with self._lock:
            now = self.clock.now()
            window = now - now % 60
            key = (token_hash, window)
            count = self._counts.get(key, 0) + 1
            self._counts[key] = count
            if count > self.limit:
                raise APIError(429, "rate_limited", headers={
                    "Retry-After": str(window + 60 - now),
                })

