"""Serialized SQLite operations. Returned timestamps are raw integer Unix seconds."""

from __future__ import annotations

from contextlib import contextmanager
import hashlib
import re
import secrets
import sqlite3
import threading

from .core import APIError, Clock, validate_create


_SCHEMA = """
PRAGMA user_version = 1;
CREATE TABLE IF NOT EXISTS tokens (
  token_hash TEXT PRIMARY KEY,
  created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS links (
  slug TEXT PRIMARY KEY,
  url TEXT NOT NULL,
  token_hash TEXT NOT NULL REFERENCES tokens(token_hash),
  created_at INTEGER NOT NULL,
  expires_at INTEGER,
  clicks INTEGER NOT NULL DEFAULT 0,
  last_clicked_at INTEGER);
"""
_LINK_COLUMNS = "slug, url, created_at, expires_at, clicks, last_clicked_at"
_ALPHABET = "abcdefghijklmnopqrstuvwxyz0123456789"
_BEARER_PATTERN = re.compile(r"Bearer (lv_[0-9a-f]{32})")
_CLICK_SQL = "UPDATE links SET clicks = clicks + 1, last_clicked_at = ? WHERE slug = ?"


def hash_token(token: str) -> str:
    return hashlib.sha256(token.encode("utf-8")).hexdigest()


class Store:
    def __init__(self, path: str, clock: Clock | None = None):
        self.clock = clock if clock is not None else Clock()
        self._lock = threading.Lock()
        self._connection = sqlite3.connect(path, check_same_thread=False)
        self._connection.row_factory = sqlite3.Row
        try:
            with self._transaction() as connection:
                connection.execute("PRAGMA foreign_keys = ON")
                connection.executescript(_SCHEMA)
        except Exception:
            self._connection.close()
            raise

    @contextmanager
    def _transaction(self):
        with self._lock:
            with self._connection:
                yield self._connection

    def close(self) -> None:
        with self._lock:
            self._connection.close()

    def issue_token(self) -> dict:
        with self._transaction() as connection:
            token = "lv_" + secrets.token_hex(16)
            now = self.clock.now()
            connection.execute(
                "INSERT INTO tokens (token_hash, created_at) VALUES (?, ?)",
                (hash_token(token), now),
            )
            return {"token": token, "created_at": now}

    def authenticate(self, authorization: str | None) -> str:
        """Validate the full Authorization header and return the stored token digest."""
        match = _BEARER_PATTERN.fullmatch(authorization) if isinstance(authorization, str) else None
        if match is None:
            raise APIError(401, "unauthorized")
        digest = hash_token(match.group(1))
        with self._transaction() as connection:
            known = connection.execute(
                "SELECT 1 FROM tokens WHERE token_hash = ?", (digest,),
            ).fetchone()
            if known is None:
                raise APIError(401, "unauthorized")
        return digest

    def create_link(self, token_hash: str, body: dict) -> dict:
        fields = validate_create(body)
        with self._transaction() as connection:
            if "slug" in fields:
                slug = fields["slug"]
                if slug == "healthz" or connection.execute(
                    "SELECT 1 FROM links WHERE slug = ?", (slug,),
                ).fetchone() is not None:
                    raise APIError(409, "slug_taken")
            else:
                for _ in range(5):
                    slug = "".join(secrets.choice(_ALPHABET) for _ in range(7))
                    if slug != "healthz" and connection.execute(
                        "SELECT 1 FROM links WHERE slug = ?", (slug,),
                    ).fetchone() is None:
                        break
                else:
                    raise APIError(500, "internal", "generated slug attempts exhausted")
            now = self.clock.now()
            expires_at = now + fields["expires_in"] if "expires_in" in fields else None
            connection.execute(
                "INSERT INTO links (slug, url, token_hash, created_at, expires_at) "
                "VALUES (?, ?, ?, ?, ?)",
                (slug, fields["url"], token_hash, now, expires_at),
            )
            return dict(connection.execute(
                f"SELECT {_LINK_COLUMNS} FROM links WHERE slug = ?", (slug,),
            ).fetchone())

    def list_links(self, token_hash: str) -> list[dict]:
        with self._transaction() as connection:
            return [dict(row) for row in connection.execute(
                f"SELECT {_LINK_COLUMNS} FROM links WHERE token_hash = ? "
                "ORDER BY created_at ASC, slug ASC", (token_hash,),
            ).fetchall()]

    def inspect_link(self, token_hash: str, slug: str) -> dict:
        with self._transaction() as connection:
            row = connection.execute(
                f"SELECT {_LINK_COLUMNS} FROM links WHERE slug = ? AND token_hash = ?",
                (slug, token_hash),
            ).fetchone()
            if row is None:
                raise APIError(404, "not_found")
            return dict(row)

    def delete_link(self, token_hash: str, slug: str) -> None:
        with self._transaction() as connection:
            deleted = connection.execute(
                "DELETE FROM links WHERE slug = ? AND token_hash = ?", (slug, token_hash),
            ).rowcount
            if not deleted:
                raise APIError(404, "not_found")

    def resolve(self, slug: str) -> str:
        with self._transaction() as connection:
            row = connection.execute(
                "SELECT url, expires_at FROM links WHERE slug = ?", (slug,),
            ).fetchone()
            if row is None:
                raise APIError(404, "not_found")
            now = self.clock.now()
            if row["expires_at"] is not None and now >= row["expires_at"]:
                raise APIError(410, "gone")
            connection.execute(_CLICK_SQL, (now, slug))
            return row["url"]

